package com.letstudy.backend.controller;
import com.letstudy.backend.model.*; import com.letstudy.backend.repository.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/lessons") public class LessonController {private final LessonRepository repo;private final TopicRepository topics;public LessonController(LessonRepository repo,TopicRepository topics){this.repo=repo;this.topics=topics;}@GetMapping public List<Lesson> all(){return repo.findAll();}@GetMapping("/topic/{topicId}") public List<Lesson> byTopic(@PathVariable Long topicId){return repo.findByTopic(topics.findById(topicId).orElseThrow());}@GetMapping("/{id}") public Lesson one(@PathVariable Long id){return repo.findById(id).orElseThrow();}@PostMapping("/topic/{topicId}") public Lesson add(@PathVariable Long topicId,@RequestBody Lesson input){Lesson l=new Lesson(input.getTitle(),input.getContent(),topics.findById(topicId).orElseThrow());return repo.save(l);}@PutMapping("/{id}") public Lesson update(@PathVariable Long id,@RequestBody Lesson input){Lesson l=repo.findById(id).orElseThrow();l.setTitle(input.getTitle());l.setContent(input.getContent());if(input.getTopic()!=null&&input.getTopic().getId()!=null)l.setTopic(topics.findById(input.getTopic().getId()).orElseThrow());return repo.save(l);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
